from openpyxl import load_workbook
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
for r in range(1,21):
    entries=[]
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if v is not None:
            entries.append(f'{ws.cell(r,c).coordinate}={v!r}')
    if entries:
        print(f'Row {r}: ' + ', '.join(entries))
